1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Normalizes the create-owner address into its canonical form (see {@link AddressNormalizer}) and
8	 * writes it back onto the body so {@link BuildOwner} maps and {@link SaveOwner} stores the
9	 * normalized value, and {@code GET} returns it. Running before {@link AssignHousehold} means every
10	 * later step sees — and therefore compares and hashes — the normalized address.
11	 *
12	 * <p>The structured form is preferred: when a non-blank {@code addressLine1} is supplied, both
13	 * lines are normalized and the flat {@code address} is set to the composed value (the normalized
14	 * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
15	 * an {@code addressLine2} is present). Without a structured line the flat {@code address} is
16	 * normalized on its own, keeping the older payload shape working unchanged.
17	 *
18	 * <p>Runs after {@link ValidateOwnerFields} (which rejects a request with an address blank in both
19	 * forms after normalization) and mutates the validated body in place — {@code @Val} yields the same
20	 * object the earlier step published.
21	 */
22	public class NormalizeOwnerAddress {
23	
24	    public void service(@Val OwnerFieldsDto request) {
25	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
26	        if (!line1.isEmpty()) {
27	            String line2 = AddressNormalizer.normalize(request.getAddressLine2());
28	            request.setAddressLine1(line1);
29	            request.setAddressLine2(line2.isEmpty() ? null : line2);
30	            request.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
31	        }
32	        else {
33	            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
34	        }
35	    }
36	}
