17	 * back-fill are needed.
18	 *
19	 * <p>The {@code householdId} is no longer part of duplicate detection (that is now the single
20	 * {@code identityKey}, keyed on telephone, email and {@code soundex(lastName)}); it survives only
21	 * to size the household for the later membership rules (see {@link CountHouseholdMembers}).
22	 *
23	 * <p>Runs after {@link BuildOwner} (so the entity — hence its last name and postcode — exists)
24	 * and before {@link CheckOwnerIdentityUnique}, mutating the built {@link Owner} in place.
25	 */
26	public class AssignHousehold {
27	
28	    public void service(@Val Owner built) {
29	        String lastName = normalize(built.getLastName());
30	        String postcode = built.getPostcode() == null ? "" : built.getPostcode();
31	        built.setHouseholdId(householdId(lastName, postcode));
32	    }
33	
34	    /** The fixed version-2 tag mixed into the hashed household input. */
35	    static final String VERSION_TAG = "V2";
36	
37	    /** A stable version-2 household identifier: first 12 hex chars of SHA-256 over the {@code 'V2'}
38	     *  tag, the normalized last name and postcode, so all members of the same household derive the
39	     *  same value while never reproducing a version-1 householdId. */
40	    static String householdId(String normalizedLastName, String postcode) {
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256")
43	                    .digest((VERSION_TAG + "|" + normalizedLastName + "|" + postcode)
44	                            .getBytes(StandardCharsets.UTF_8));
45	            StringBuilder sb = new StringBuilder(digest.length * 2);
46	            for (byte b : digest) {
47	                sb.append(String.format("%02x", b));
48	            }
49	            return sb.substring(0, 12);
50	        }
51	        catch (NoSuchAlgorithmException e) {
52	            throw new IllegalStateException("SHA-256 not available", e);
53	        }
54	    }
55	
56	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
57	    private static String normalize(String value) {
58	        if (value == null) {
59	            return "";
60	        }
61	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
62	    }
63	}
